import {
  Button,
  Field,
  MessageProvider,
  Select,
  useMessage,
  type MessageType,
} from '@dg-pc/components';
import styles from './MessagePreview.module.css';

const content: Record<MessageType, string> = {
  success: '\u8BA2\u5355\u4FDD\u5B58\u6210\u529F',
  warning: '\u90E8\u5206\u5546\u54C1\u5E93\u5B58\u4E0D\u8DB3\uFF0C\u8BF7\u68C0\u67E5\u540E\u518D\u63D0\u4EA4',
  error: '\u4FDD\u5B58\u5931\u8D25\uFF0C\u8BF7\u7A0D\u540E\u91CD\u8BD5',
};

function DemoContent({ stageRef }: { stageRef: React.RefObject<HTMLDivElement | null> }) {
  const message = useMessage();
  const [duration, setDuration] = useState(3000);

  const show = (type: MessageType) => message[type](content[type], { duration });

  const showStack = () => {
    message.success(content.success, { duration });
    message.warning(content.warning, { duration });
    message.error(content.error, { duration });
  };

  return (
    <div className={styles.demo}>
      <div className={styles.intro}>
        <h3>\u7C7B\u578B\u3001\u6301\u7EED\u65F6\u95F4\u4E0E\u53E0\u653E</h3>
        <p>\u9009\u62E9\u6301\u7EED\u65F6\u95F4\u540E\u89E6\u53D1\u6210\u529F\u3001\u8B66\u544A\u6216\u9519\u8BEF\u63D0\u793A\uFF1B\u5E38\u9A7B\u63D0\u793A\u53EF\u624B\u52A8\u5173\u95ED\uFF0C\u53E0\u653E\u6700\u591A\u5C55\u793A\u4E09\u6761\u3002</p>
      </div>
      <section className={styles.stage} ref={stageRef}>
        <div className={styles.controls}>
          <Field label="\u6301\u7EED\u65F6\u95F4" htmlFor="message-duration"><Select id="message-duration" value={String(duration)} onChange={(value) => { if (value !== null) setDuration(Number(value)); }} options={[{ key: '3000', label: '3 \u79D2\uFF08\u81EA\u52A8\u5173\u95ED\uFF09' }, { key: '0', label: '\u5E38\u9A7B\uFF08\u53EF\u624B\u52A8\u5173\u95ED\uFF09' }]} /></Field>
          <div className={styles.actions}>
            <Button onPress={() => show('success')}>\u6210\u529F\u63D0\u793A</Button>
            <Button onPress={() => show('warning')}>\u8B66\u544A\u63D0\u793A</Button>
            <Button onPress={() => show('error')}>\u9519\u8BEF\u63D0\u793A</Button>
            <Button onPress={showStack}>\u53E0\u653E\u6F14\u793A</Button>
            <Button onPress={message.clear}>\u6E05\u7A7A</Button>
          </div>
        </div>
      </section>
    </div>
  );
}

export default function Scenarios() {
  const stageRef = useRef<HTMLDivElement>(null);
  const getContainer = useCallback(() => stageRef.current, []);

  return (
    <MessageProvider getContainer={getContainer} maxCount={3}>
      <DemoContent stageRef={stageRef} />
    </MessageProvider>
  );
}

